/**
 * Resume business logic.
 *
 * All database access for resumes happens here. Controllers are thin HTTP
 * adapters that delegate to this service.
 */

import { eq, desc, and, ilike, count, ne, type SQL } from 'drizzle-orm';
import { getDb, schema, type NewResume } from '../../db/index.js';
import type {
  ResumeFilters,
  PaginateParams,
  PaginatedResumes,
  ResumeRow,
} from '../resumes/types.js';
import type { ResumeDraft } from '@resume-builder/types';
import { z } from 'zod';
import { HttpError } from '../../middleware/error.js';

const db = getDb();

// Ids are generated by the shared `createId()` helper (e.g. `res_lx8f2a_9kd1`),
// so we validate shape rather than forcing a UUID.
const resumeIdSchema = z.string().min(1).max(64);
const resumeSlugSchema = z.string().min(1).max(100);

function requireValidId(id: unknown): string {
  return resumeIdSchema.parse(id);
}

function requireValidSlug(slug: unknown): string {
  return resumeSlugSchema.parse(slug);
}

/** Turn a title into a URL-safe slug. */
export function slugify(text: string): string {
  return (
    text
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 60) || 'resume'
  );
}

/**
 * Resolve a slug that is unique across every account.
 *
 * The slug is the public, shareable identifier for a resume, so it has to be
 * unique globally. Titles repeat constantly (the dashboard always starts from
 * "New Resume"), so a short random suffix is appended when the base slug is
 * already taken.
 *
 * `excludeId` keeps a resume from colliding with itself when it is renamed.
 */
async function resolveSlug(desired: string, excludeId?: string): Promise<string> {
  const base = slugify(desired);

  for (let attempt = 0; attempt < 5; attempt += 1) {
    const candidate =
      attempt === 0
        ? base
        : `${base}-${Math.random().toString(36).slice(2, 7)}`;
    const conditions: SQL[] = [eq(schema.resumes.slug, candidate)];
    if (excludeId) conditions.push(ne(schema.resumes.id, excludeId));
    const existing = await db
      .select({ id: schema.resumes.id })
      .from(schema.resumes)
      .where(and(...conditions))
      .limit(1);
    if (!existing[0]) return candidate;
  }

  return `${base}-${Date.now().toString(36)}`;
}

/** Project a database row into the canonical resume shape returned by the API. */
function rowToResume(row: typeof schema.resumes.$inferSelect): ResumeRow {
  return {
    id: row.id,
    userId: row.userId,
    title: row.title,
    slug: row.slug,
    metadata: row.metadata as unknown as ResumeRow['metadata'],
    content: row.content as unknown as ResumeRow['content'],
    createdAt: new Date(row.createdAt).toISOString(),
    updatedAt: new Date(row.updatedAt).toISOString(),
  };
}

// ---------------------------------------------------------------------------
// List / filter / pagination
// ---------------------------------------------------------------------------

/** List resumes for a user with optional filtering and pagination. */
export async function listResumes(
  filters: ResumeFilters,
  params: PaginateParams
): Promise<PaginatedResumes> {
  const page = Math.max(params.page ?? 1, 1);
  const limit = Math.min(Math.max(params.limit ?? 20, 1), 100);
  const offset = (page - 1) * limit;

  // `requireAuth` guarantees req.user exists; list only the caller's resumes.
  const filtersId = filters.userId ?? '__none__';
  const conditions: SQL[] = [eq(schema.resumes.userId, filtersId)];
  if (filters.search) {
    conditions.push(ilike(schema.resumes.title, `%${filters.search}%`));
  }

  const totalResult = await db
    .select({ count: count() })
    .from(schema.resumes)
    .where(and(...conditions));
  const total = Number(totalResult[0]?.count ?? 0);

  const rows = await db
    .select()
    .from(schema.resumes)
    .where(and(...conditions))
    .orderBy(desc(schema.resumes.updatedAt))
    .limit(limit)
    .offset(offset);

  const items = rows.map((row) => rowToResume(row));
  return { items, total, page, limit };
}

// ---------------------------------------------------------------------------
// Get / create / update / delete
// ---------------------------------------------------------------------------

/** Get a single resume by ID. User must own it. */
export async function getResume(id: string, userId?: string): Promise<ResumeRow> {
  requireValidId(id);
  const conditions: SQL[] = [eq(schema.resumes.id, id)];
  if (userId) conditions.push(eq(schema.resumes.userId, userId));

  const rows = await db
    .select()
    .from(schema.resumes)
    .where(and(...conditions))
    .limit(1);

  if (!rows[0]) throw new HttpError(404, 'Resume not found');
  return rowToResume(rows[0]);
}

/** Create a new resume. */
export async function createResume(data: ResumeDraft, userId?: string): Promise<ResumeRow> {
  const now = new Date().toISOString();
  const id = requireValidId(data.id ?? crypto.randomUUID());
  const slug = requireValidSlug(
    await resolveSlug(data.slug ?? data.title)
  );

  const newResume: NewResume = {
    id,
    userId: userId ?? null,
    title: data.title,
    slug,
    metadata: data.metadata as unknown as Record<string, unknown>,
    content: data.content as unknown as Record<string, unknown>,
    createdAt: new Date(now),
    updatedAt: new Date(now),
  };

  await db.insert(schema.resumes).values(newResume);

  return {
    id,
    userId: newResume.userId ?? null,
    title: newResume.title,
    slug: newResume.slug,
    metadata: newResume.metadata as unknown as ResumeRow['metadata'],
    content: newResume.content as unknown as ResumeRow['content'],
    createdAt: new Date(now).toISOString(),
    updatedAt: new Date(now).toISOString(),
  };
}

/** Partially update a resume. User must own it. */
export async function updateResume(
  id: string,
  data: Partial<ResumeDraft>,
  userId?: string
): Promise<ResumeRow> {
  requireValidId(id);
  await getResume(id, userId); // throws 404 if not found / not owned

  const now = new Date();
  const updates: Record<string, unknown> = { updatedAt: now };

  if (data.title !== undefined) updates.title = data.title;
  if (data.metadata !== undefined) updates.metadata = data.metadata;
  if (data.content !== undefined) updates.content = data.content;
  if (data.slug !== undefined) {
    updates.slug = await resolveSlug(data.slug, id);
  }

  await db.update(schema.resumes).set(updates).where(eq(schema.resumes.id, id));
  return getResume(id, userId);
}

/** Delete a resume. User must own it. */
export async function deleteResume(id: string, userId?: string): Promise<void> {
  requireValidId(id);
  await getResume(id, userId); // throws 404 if not found / not owned
  await db.delete(schema.resumes).where(eq(schema.resumes.id, id));
}
